TUTORIALS = []

TUTORIALS.append({'title': 'COL-1. Setup: folders, INSTALLED_APPS, urls', 'category': 'programming', 'order': 1, 'summary': 'Do this first: the app layout and settings.', 'content': '<p>Step 1 of 12. Create the app folder with this layout. <code>__init__.py</code> is empty. Add <code>"collateral"</code> to <code>INSTALLED_APPS</code> and include its urls. There are no models, so no migrations.</p>\n<p>Needs <code>oracledb</code>, <code>pandas</code>, <code>pyarrow</code> (parquet) and <code>openpyxl</code> (Excel). The folder <code>BASE_DIR/datasets/collateral/</code> is created by itself on the first download.</p>\n<p>In <code>queries.py</code> change three things: the line <code>from main.oracle import get_oracle_connection</code>, the three table names (<code>DEAL_TABLE</code>, <code>PARAM_TABLE</code>, <code>PARENT_TABLE</code>) and, if your tables have no <code>date_from</code>, the <code>ON_DATE</code> line. Then open <code>/collateral/params/</code>: it lists every parameter in the database, so you can find the address field and add it to <code>PROPERTY</code>.</p>\n<p>Sidebar link in base.html: <code>{% url \'collateral\' %}</code>, icon <code>fa-solid fa-shield-halved</code>.</p>\n<h3>Layout</h3>\n<pre><code class="language-plaintext">collateral/\n    __init__.py\n    apps.py\n    urls.py\n    forms.py\n    queries.py\n    process.py\n    views.py\n    templates/collateral/style.html\n    templates/collateral/card.html\n    templates/collateral/page.html\n    templates/collateral/deal.html\n    templates/collateral/params.html\n</code></pre>\n<h3>urls.py of the project</h3>\n<pre><code class="language-python">path("collateral/", include("collateral.urls")),\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-2. apps.py', 'category': 'programming', 'order': 2, 'summary': 'App config.', 'content': '<p>Step 2 of 12. Save as <code>collateral/apps.py</code>.</p>\n<h3>apps.py</h3>\n<pre><code class="language-python">from django.apps import AppConfig\n\n\nclass CollateralConfig(AppConfig):\n    default_auto_field = "django.db.models.BigAutoField"\n    name = "collateral"\n    verbose_name = "Обеспечение"\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-3. urls.py', 'category': 'programming', 'order': 3, 'summary': 'Five pages: the drill-down, one deal, Excel, the parquet file, parameters + SQL.', 'content': '<p>Step 3 of 12. Save as <code>collateral/urls.py</code>.</p>\n<h3>urls.py</h3>\n<pre><code class="language-python">from django.urls import path\nfrom . import views\n\nurlpatterns = [\n    path("", views.home, name="collateral"),\n    path("deal/&lt;str:dealid&gt;/", views.deal, name="collateral-deal"),\n    path("excel/", views.excel, name="collateral-excel"),\n    path("file/", views.parquet_file, name="collateral-file"),\n    path("params/", views.params, name="collateral-params"),\n]\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-4. forms.py', 'category': 'programming', 'order': 4, 'summary': 'The date form (and the «load again from the database» tick).', 'content': '<p>Step 4 of 12. Save as <code>collateral/forms.py</code>.</p>\n<h3>forms.py</h3>\n<pre><code class="language-python">"""The one form of the app: which date, and whether to ask the database again."""\nfrom django import forms\n\n\nclass DayForm(forms.Form):\n    date = forms.DateField(\n        label="Дата",\n        widget=forms.DateInput(attrs={"type": "date", "class": "form-control"}, format="%Y-%m-%d"),\n    )\n    refresh = forms.BooleanField(\n        label="Загрузить заново из базы",\n        required=False,\n        widget=forms.CheckboxInput(attrs={"class": "form-check-input"}),\n    )\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-5. queries.py', 'category': 'programming', 'order': 5, 'summary': 'All the SQL. The three old scripts (avto / nedvijimost / others) as three parameter dicts and ONE skeleton. Change the import line, the three table names and ON_DATE.', 'content': '<p>Step 5 of 12. Save as <code>collateral/queries.py</code>.</p>\n<h3>queries.py</h3>\n<pre><code class="language-python">"""\nAll the SQL of the collateral app, and nothing else.\n\nHOW IT WORKS\nYour three old scripts (others / nedvijimost / avto) were three long SQLs with the same\nskeleton and a different list of parameters. Here the skeleton is written ONCE\n(the function make_sql) and the parameters are three Python dicts:\n\n    CARS       → «avto»\n    PROPERTY   → «nedvijimost»\n    OTHERS     → «others», split into small groups (equipment, deposit, insurance ...)\n\nEach line of a dict is:   "NAME_IN_DATABASE": ("column_name", "Название по-русски"),\nTo add a field: add one line. The SQL, the Excel file and the deal page pick it up.\nTo see which parameters exist at all, open the «Параметры» page of the app.\n\nWHAT TO CHANGE FOR YOUR DATABASE\n1. The import line of get_oracle_connection (just below).\n2. The three table names (DEAL_TABLE, PARAM_TABLE, PARENT_TABLE).\n3. ON_DATE, if your tables have no date_from column (see the comment there).\n\nTo run a query by hand in your SQL tool: open the «Параметры» page, it prints the\nfinished SQL. Replace :pdate with a date, e.g.  date \'2026-10-01\'.\n"""\nimport pandas as pd\n\n# ⚠️ Change this one line to wherever your get_oracle_connection() lives.\nfrom main.oracle import get_oracle_connection\n\n\n# ── 1. TABLES (placeholders: put your real schema.table here) ──────────────────────\nDEAL_TABLE = "schema1.second_deal"              # the collateral itself: amount, currency ...\nPARAM_TABLE = "schema1.second_deal_dop_param"   # extra parameters: dealid, paramname, paramvalue\nPARENT_TABLE = "schema2.deal"                   # link to the анкета/РНК and ТОБО\nCOLLATERAL_TYPE = 357                           # dealtypeid of a collateral deal in PARENT_TABLE\n\n\n# ── 2. WHICH VERSION OF A ROW COUNTS ON THE CHOSEN DATE ────────────────────────────\n# Both tables keep history: a new row every time something changes, closed by date_to.\n# The row that was valid on :pdate is the one with  date_from &lt;= :pdate &lt; date_to.\n# If your tables have NO date_from column, use this line instead (it takes every version\n# still open on the date, and the newest of them wins):\n#     ON_DATE = "{t}.date_to &gt; :pdate"\nON_DATE = "{t}.date_from &lt;= :pdate and {t}.date_to &gt; :pdate"\n\n\n# ── 3. PARAMETERS ──────────────────────────────────────────────────────────────────\n# "NAME_IN_DATABASE": ("column_name", "Название по-русски")\n# column_name: short, latin, at most 30 characters (Oracle\'s limit for an alias).\n\nCARS = {\n    "TRANSPORT_TYPE":      ("transport_type", "Тип транспорта"),\n    "TRANS_MAN_NEW":       ("brand_main", "Марка"),\n    "TRANSP_МАРКА":        ("brand_other", "Марка (если другое)"),   # yes, МАРКА is Cyrillic in the database\n    "TRANS_MOD_NEW":       ("model_main", "Модель"),\n    "TRANSP_MODEL":        ("model_other", "Модель (если другое)"),\n    "COMPLECT":            ("trim", "Модель и комплектация"),\n    "LICENSE_PLATE":       ("plate", "Госномер"),\n    "PRODUCTION_YEAR":     ("made_year", "Год производства"),\n    "TRANSMISSION_TYPE":   ("gearbox", "Коробка передач"),\n    "TRANSP_COLOR":        ("color", "Цвет"),\n    "TYPE OF FUEL":        ("fuel", "Вид топлива"),\n    "TECH_PASP_SN":        ("pasp_sn", "Серия и номер техпаспорта"),\n    "TECH_PASP_D":         ("pasp_date", "Дата техпаспорта"),\n    "TECH_PASP_EXP_D":     ("pasp_end", "Техпаспорт действует до"),\n    "TECH_SERIAL":         ("pasp_serial", "Серия техпаспорта"),\n    "TECH_NUM":            ("pasp_number", "Номер техпаспорта"),\n    "TECH_ISSUE":          ("pasp_issuer", "Кто выдал техпаспорт"),\n    "BODY_N":              ("body_no", "Номер кузова"),\n    "ENGINE_NUMBER":       ("engine_no", "Номер двигателя"),\n    "CHASSIS_N":           ("chassis_no", "Номер шасси"),\n    "INVENTORY_N":         ("inventory_no", "Инвентарный номер"),\n    "TRANSP_RUN":          ("mileage", "Пробег"),\n    "ORIG_COUNTRY":        ("country", "Страна производителя"),\n    "CAR_PURCHASE_MARKET": ("buy_market", "Рынок приобретения"),\n    "CARPRICE":            ("car_price", "Стоимость по договору купли-продажи"),\n    "VEHICLE_ID":          ("vehicle_id", "Уникальный код ТС"),\n    "TYPEREGNEWCAR":       ("reg_type", "Вид регистрации нового авто"),\n    "VEHICLE_ADD_INFO":    ("car_info", "Доп. информация о ТС"),\n}\n\nPROPERTY = {\n    "ECONOM_ZONE":         ("econ_zone", "Экономическая зона"),\n    "REGISTR_ORG_CADASTR": ("cadastre_org", "Регистрирующий орган кадастра"),\n    "CADASTR_N":           ("cadastre_no", "Кадастровый номер"),\n    "CADASTRAMOUNT":       ("cadastre_value", "Кадастровая стоимость"),\n    "BUILDING_KIND":       ("building_kind", "Вид недвижимости"),\n    "BUILDING_TYPE":       ("building_type", "Тип недвижимости"),\n    "TO_EXPL_D":           ("in_use_date", "Дата ввода в эксплуатацию"),\n    "YEAR_CONSTRUCTION":   ("built_year", "Год постройки"),\n    "PROPERTY_AREA":       ("total_area", "Общая площадь, м²"),\n    "LAND_AREA":           ("land_area", "Площадь участка, м²"),\n    "BUILT_UP_AREA":       ("built_area", "Площадь застройки, м²"),\n    "EFFECTIVE_AREA":      ("useful_area", "Полезная площадь, м²"),\n    "LIVING_SPACE":        ("living_area", "Жилая площадь, м²"),\n    "ROOM_CNT":            ("rooms", "Количество комнат"),\n    # The address is not in your old script. Find its real name on the «Параметры» page\n    # (look for ADDR / ADRES / REGION / DISTRICT), then remove the # here:\n    # "ADDRESS":           ("address", "Адрес"),\n}\n\n# «Others» is many small kinds of collateral. Each group is one kind; a deal belongs to\n# the FIRST group (in this order) that has at least one of its parameters filled.\nOTHERS = {\n    "equipment": {\n        "EQUIPMENT_TYPE":         ("eq_type", "Тип оборудования"),\n        "EQUIPMENT_NAME":         ("eq_name", "Наименование оборудования"),\n        "EQUIP_BRAND_MODEL":      ("eq_model", "Марка / модель"),\n        "EQUIP_MANUFACTURER":     ("eq_maker", "Производитель"),\n        "EQUIP_ORIG_COUNTRY":     ("eq_country", "Страна производства"),\n        "EQUIP_ORIG_Y":           ("eq_year", "Год производства"),\n        "EQUIP_ORIG_N":           ("eq_serial", "Заводской номер"),\n        "EQUIP_BEG_TO_EXPL_D":    ("eq_in_use", "Дата ввода в эксплуатацию"),\n        "EQUIP_TITLE_DOC_N":      ("eq_doc_no", "Номер правоустанавливающего документа"),\n        "EQUIP_TITLE_DOC_D":      ("eq_doc_date", "Дата правоустанавливающего документа"),\n        "EQUIP_UQ_ACC_NUMBER":    ("eq_uid", "Уникальный учётный номер"),\n        "EQUIP_ACQUISITION COST": ("eq_cost", "Стоимость приобретения"),\n    },\n    "deposit": {\n        "DEPOSIT_TYPE_N":    ("dep_type", "Код типа депозита"),\n        "DEPOSIT_NAME":      ("dep_name", "Наименование депозита"),\n        "DEPOSIT_ENDDATE":   ("dep_end", "Дата истечения депозита"),\n        "DEP_BANK_BRANCH_N": ("dep_branch", "Отделение, где размещён депозит"),\n    },\n    "securities": {\n        "SEC_NAME":            ("sec_name", "Наименование ценной бумаги"),\n        "SEC_TOTAL_CNT":       ("sec_count", "Количество ценных бумаг"),\n        "NOMINAL_VAL_ONE_SEC": ("sec_nominal", "Номинал одной бумаги"),\n        "SEC_TOTAL_AMOUNT":    ("sec_total", "Общая сумма ценных бумаг"),\n        "DISCOUNT_AMOUNT":     ("sec_discount", "Сумма дисконта"),\n        "SEC_ISSUE_DATE":      ("sec_issue", "Дата выпуска"),\n        "SEC_PAY_DATE":        ("sec_pay_date", "Дата погашения"),\n        "DEPOSITORY":          ("depository", "Депозитарий"),\n        "ACC_IN_DEPOSITORY":   ("sec_account", "Счёт в депозитарии"),\n    },\n    "goods": {\n        "PRODUCTNAME":         ("goods_name", "Наименование товара"),\n        "BOOKVALUE":           ("goods_book", "Балансовая стоимость ТМЦ (валюта залога)"),\n        "BOOKVALUEEQUIVALENT": ("goods_book_eq", "Балансовая стоимость ТМЦ (эквивалент)"),\n        "DESCRIPDATE":         ("goods_list_date", "Дата расшифровки остатка ТМЦ"),\n        "ACTDATE":             ("goods_act_date", "Дата акта согласования стоимости"),\n    },\n    "insurance": {\n        "POLIS_NUM":  ("policy_no", "Номер страхового полиса"),\n        "POLIS_DATE": ("policy_date", "Дата страхового полиса"),\n    },\n    "land": {\n        "LAND_LEASE_CADASTR_N": ("land_cadastre_no", "Кадастровый номер (аренда земли)"),\n        "LAND_LEASE_AREA":      ("land_lease_area", "Площадь (аренда земли)"),\n    },\n    "harvest": {\n        "FUTURE_HARVEST_AREA":      ("harvest_area", "Площадь (будущий урожай)"),\n        "FUTURE_HARVEST_CROP_AREA": ("harvest_crop_area", "Посевная площадь, га"),\n    },\n    "jewelry": {\n        "JEWELRY_CNT":    ("jewel_count", "Количество изделий"),\n        "JEWELRY_WEIGHT": ("jewel_weight", "Вес"),\n    },\n    "rights": {\n        "REQUIREMENTOBJECT": ("rights_object", "Объект имущественного права"),\n        "NAMEACQUIRED":      ("rights_asset", "Приобретаемое имущество"),\n    },\n    "guarantee": {\n        "SET_GARANT_DEP_ACC": ("guarantee_on_dep", "Гарантия внесена на депозитный счёт"),\n        "IS_SUP_DOCUMENTS":   ("has_documents", "Есть подтверждающие документы"),\n    },\n}\n\n# Parameters every kind can have. They are fetched too, but having ONLY these\n# does not make a deal a car / a property / an «other».\nCOMMON = {\n    "PROVISION_SOURCE": ("source", "Источник приобретения обеспечения"),\n}\n\n\ndef others_flat():\n    """All the «others» groups as one dict, like CARS and PROPERTY."""\n    flat = {}\n    for group in OTHERS.values():\n        flat.update(group)\n    return flat\n\n\ndef all_labels():\n    """column_name → Russian label, for every parameter (used by the deal page and Excel)."""\n    labels = {}\n    for params in [CARS, PROPERTY, others_flat(), COMMON]:\n        for column, label in params.values():\n            labels[column] = label\n    return labels\n\n\ndef quoted(names):\n    """[\'A\', \'B\'] → "\'A\', \'B\'"  (for an IN list)."""\n    return ", ".join("\'" + name + "\'" for name in names)\n\n\ndef make_sql(params):\n    """\n    The one skeleton behind all three queries. One row per collateral deal that has\n    at least one of `params` filled on :pdate, with each parameter in its own column.\n\n      deals   — the collateral row valid on the date (amount, currency, branch ...)\n      params  — the parameter values valid on the date, one row per (deal, parameter)\n      wide    — the same values turned into columns: one row per deal\n    """\n    names = list(params) + list(COMMON)\n    columns = ",\\n           ".join(\n        f"max(case when paramname = \'{name}\' then paramvalue end) as {column}"\n        for name, (column, label) in {**params, **COMMON}.items()\n    )\n    return f"""\nwith deals as (\n    select id, siteid, currencyid, amounteq, marketamount, creditnbusupplyid, securitydescription\n    from (\n        select d.*,\n               row_number() over (partition by d.id order by d.date_to desc) as rn\n        from   {DEAL_TABLE} d\n        where  {ON_DATE.format(t=\'d\')}\n    )\n    where rn = 1\n),\nparams as (\n    select dealid, paramname, paramvalue\n    from (\n        select v.dealid, v.paramname, v.paramvalue,\n               row_number() over (partition by v.dealid, v.paramname order by v.date_to desc) as rn\n        from   {PARAM_TABLE} v\n        where  {ON_DATE.format(t=\'v\')}\n        and    v.paramname in ({quoted(names)})\n    )\n    where rn = 1\n),\nwide as (\n    select dealid,\n           {columns}\n    from   params\n    group by dealid\n    having count(case when paramname in ({quoted(params)}) then 1 end) &gt; 0\n)\nselect w.*,\n       d.siteid                  as mfo,\n       p.toboid                  as tobo,\n       p.parentid                as parent_id,\n       d.currencyid              as currency,\n       d.amounteq / 100          as amount,\n       d.marketamount / 100      as market,\n       d.creditnbusupplyid       as subtype,\n       d.securitydescription     as note\nfrom   wide w\nleft join deals d          on d.id = w.dealid\nleft join {PARENT_TABLE} p on p.id = w.dealid and p.dealtypeid = {COLLATERAL_TYPE}\n"""\n\n\nSQL_CARS = make_sql(CARS)\nSQL_PROPERTY = make_sql(PROPERTY)\nSQL_OTHERS = make_sql(others_flat())\n\n# Every parameter name that exists on the date, how many collateral deals have it and\n# one example value. Shown on the «Параметры» page: that is where you find the address.\nSQL_PARAM_NAMES = f"""\nselect v.paramname,\n       count(distinct v.dealid) as deals,\n       max(v.paramvalue)        as example\nfrom   {PARAM_TABLE} v\nwhere  {ON_DATE.format(t=\'v\')}\nand    v.dealid in (select id from {PARENT_TABLE} where dealtypeid = {COLLATERAL_TYPE})\ngroup by v.paramname\norder by deals desc\n"""\n\n\ndef run(cursor, sql, pdate):\n    """Run one query and return it as a pandas table with lower-case column names."""\n    cursor.arraysize = 5000                     # fetch in big packs: much faster on 100 000+ rows\n    cursor.execute(sql, {"pdate": pdate})\n    columns = [c[0].lower() for c in cursor.description]\n    return pd.DataFrame(cursor.fetchall(), columns=columns)\n\n\ndef load_day(pdate):\n    """The three queries for one date: {\'car\': table, \'property\': table, \'other\': table}."""\n    with get_oracle_connection() as conn:\n        cursor = conn.cursor()\n        return {\n            "car": run(cursor, SQL_CARS, pdate),\n            "property": run(cursor, SQL_PROPERTY, pdate),\n            "other": run(cursor, SQL_OTHERS, pdate),\n        }\n\n\ndef load_param_names(pdate):\n    """The «Параметры» page: every parameter name on the date."""\n    with get_oracle_connection() as conn:\n        return run(conn.cursor(), SQL_PARAM_NAMES, pdate)\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-6. process.py', 'category': 'programming', 'order': 6, 'summary': 'Oracle → parquet in datasets/collateral/ → clean pandas table → cards, KPIs, data checks. All the settings (buckets, codes, cards) are at the top.', 'content': '<p>Step 6 of 12. Save as <code>collateral/process.py</code>.</p>\n<h3>process.py</h3>\n<pre><code class="language-python">"""\nEverything between the database and the page: save, read, clean, count.\n\nTHE ROAD OF THE DATA\n1. save_day(day)     Oracle → one parquet file per date in datasets/collateral/.\n                     The database is asked only once per date (or when you tick\n                     «Загрузить заново»). The file keeps the raw values, as text.\n2. read_day(day)     parquet → prepare() → a clean pandas table, kept in memory,\n                     so clicking around the page does not read the file again.\n3. prepare(table)    numbers become numbers, dates become dates, spelling variants of\n                     the same brand are merged, and the extra columns the page groups by\n                     are added (brand, age_group, area_group, dep_term ...).\n4. build_page(...)   the filtered table → KPIs, cards, the list of deals.\n\nTHE TABLE (one row = one collateral deal)\n    kind       car / property / other\n    subkind    for «other»: equipment, deposit, insurance ... (see queries.OTHERS)\n    dealid, mfo, tobo, parent_id, currency, amount, market, subtype, note\n    + one column per parameter (names from the dicts in queries.py)\n    + the extra columns made by prepare()\n\nAll the settings you may want to change are in the block just below.\n"""\nimport numbers\nfrom datetime import date\nfrom pathlib import Path\n\nimport pandas as pd\nfrom django.conf import settings\n\nfrom . import queries\n\n\n# ═══════════════════════════════ SETTINGS ═══════════════════════════════════════════\n\nDATA_DIR = Path(settings.BASE_DIR) / "datasets" / "collateral"\nTOP = 12              # rows in a card; the rest goes into «Остальные»\nPAGE_SIZE = 50        # deals per page in the list\nEMPTY = "не указано"  # what an empty value is called in the cards\n\nKINDS = {\n    "car":      {"label": "Автотранспорт", "icon": "fa-car"},\n    "property": {"label": "Недвижимость", "icon": "fa-building"},\n    "other":    {"label": "Прочее обеспечение", "icon": "fa-layer-group"},\n}\n\n# The groups of «others» (same keys as queries.OTHERS): name and icon.\nSUBKINDS = {\n    "equipment":  {"label": "Оборудование", "icon": "fa-gears"},\n    "deposit":    {"label": "Депозиты", "icon": "fa-piggy-bank"},\n    "securities": {"label": "Ценные бумаги", "icon": "fa-chart-line"},\n    "goods":      {"label": "Товары в обороте (ТМЦ)", "icon": "fa-boxes-stacked"},\n    "insurance":  {"label": "Страховые полисы", "icon": "fa-shield-halved"},\n    "land":       {"label": "Право аренды земли", "icon": "fa-map-location-dot"},\n    "harvest":    {"label": "Будущий урожай", "icon": "fa-wheat-awn"},\n    "jewelry":    {"label": "Ювелирные изделия", "icon": "fa-gem"},\n    "rights":     {"label": "Имущественные права", "icon": "fa-file-contract"},\n    "guarantee":  {"label": "Гарантии", "icon": "fa-handshake"},\n}\n\n# Parameters that are money in TIYIN (divided by 100), as in the old scripts.\n# If another one turns out to be in tiyin too (BOOKVALUE?), add its column here.\nMONEY = ["car_price", "cadastre_value", "eq_cost", "sec_discount"]\n\n# Parameters that are plain numbers (areas, counts, mileage ...).\nNUMBERS = ["mileage", "total_area", "land_area", "built_area", "useful_area", "living_area",\n           "rooms", "sec_count", "sec_nominal", "sec_total", "goods_book", "goods_book_eq",\n           "land_lease_area", "harvest_area", "harvest_crop_area", "jewel_count", "jewel_weight"]\n\nYEARS = ["made_year", "built_year", "eq_year"]\n\nDATES = ["pasp_date", "pasp_end", "in_use_date", "eq_in_use", "eq_doc_date", "dep_end",\n         "sec_issue", "sec_pay_date", "goods_list_date", "goods_act_date", "policy_date"]\n\n# The ways a date may be written in paramvalue. The first that fits wins.\nDATE_FORMATS = ["%d.%m.%Y", "%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S", "%d/%m/%Y"]\n\n# Codes → names. If a column holds codes (1, 2, 3 ...) instead of words, add it here:\n#     "fuel": {"1": "Бензин", "2": "Метан", "3": "Пропан"},\nCODES = {\n    "currency": {"0": "UZS", "000": "UZS", "860": "UZS", "840": "USD", "978": "EUR",\n                 "643": "RUB", "826": "GBP", "756": "CHF", "156": "CNY", "392": "JPY",\n                 "398": "KZT"},\n}\n\n# Words that mean «look in the other column» (Марка = «Другое» → take «Марка (если другое)»).\nOTHER_WORDS = ["ДРУГОЕ", "ДРУГАЯ", "ДРУГОЙ", "ПРОЧЕЕ", "ПРОЧИЕ", "BOSHQA", "OTHER"]\n\n# Values that mean «nothing here».\nBLANKS = ["", "-", "—", "NULL", "null", "None", "none", "nan", "N/A"]\n\n# THE CARDS. Each card is one breakdown: (column, title, icon, order)\n#   order "amount" = biggest sum first;  "label" = in the natural order (years, buckets).\nCARS_CARDS = [\n    ("brand", "Марка", "fa-car", "amount"),\n    ("model", "Модель", "fa-car-side", "amount"),\n    ("made_year", "Год выпуска", "fa-calendar", "label"),\n    ("age_group", "Возраст автомобиля", "fa-hourglass-half", "label"),\n    ("transport_type", "Тип транспорта", "fa-truck", "amount"),\n    ("fuel", "Вид топлива", "fa-gas-pump", "amount"),\n    ("gearbox", "Коробка передач", "fa-gears", "amount"),\n    ("color", "Цвет", "fa-palette", "amount"),\n    ("country", "Страна производителя", "fa-earth-asia", "amount"),\n    ("buy_market", "Рынок приобретения", "fa-store", "amount"),\n    ("pasp_state", "Техпаспорт", "fa-id-card", "label"),\n]\nPROPERTY_CARDS = [\n    ("building_kind", "Вид недвижимости", "fa-house", "amount"),\n    ("building_type", "Тип недвижимости", "fa-city", "amount"),\n    ("area_group", "Общая площадь", "fa-ruler-combined", "label"),\n    ("rooms_group", "Комнат", "fa-door-open", "label"),\n    ("built_decade", "Год постройки", "fa-calendar", "label"),\n    ("econ_zone", "Экономическая зона", "fa-map", "amount"),\n    ("cadastre_org", "Регистрирующий орган", "fa-landmark", "amount"),\n    ("address", "Адрес", "fa-location-dot", "amount"),     # shows once ADDRESS is in queries.py\n]\nOTHERS_CARDS = [\n    ("subkind", "Вид обеспечения", "fa-layer-group", "amount"),\n]\n# Extra cards when one group of «others» is open.\nSUBKIND_CARDS = {\n    "equipment": [("eq_type", "Тип оборудования", "fa-gears", "amount"),\n                  ("eq_maker", "Производитель", "fa-industry", "amount"),\n                  ("eq_country", "Страна производства", "fa-earth-asia", "amount"),\n                  ("eq_year", "Год производства", "fa-calendar", "label")],\n    "deposit":   [("dep_type", "Тип депозита", "fa-piggy-bank", "amount"),\n                  ("dep_term", "До истечения депозита", "fa-hourglass-half", "label"),\n                  ("dep_branch", "Отделение депозита", "fa-building-columns", "amount")],\n    "securities": [("sec_name", "Ценная бумага", "fa-chart-line", "amount"),\n                   ("depository", "Депозитарий", "fa-vault", "amount"),\n                   ("sec_term", "До погашения", "fa-hourglass-half", "label")],\n    "goods":     [("goods_name", "Товар", "fa-boxes-stacked", "amount")],\n    "insurance": [("policy_year", "Год полиса", "fa-calendar", "label")],\n    "rights":    [("rights_object", "Объект права", "fa-file-contract", "amount")],\n    "guarantee": [("guarantee_on_dep", "Гарантия на депозитном счёте", "fa-handshake", "amount"),\n                  ("has_documents", "Подтверждающие документы", "fa-file-circle-check", "amount")],\n}\n# Cards on every page.\nCOMMON_CARDS = [\n    ("size_group", "Сумма залога", "fa-scale-balanced", "label"),\n    ("currency_name", "Валюта", "fa-coins", "amount"),\n    ("mfo", "Филиал (МФО)", "fa-building-columns", "amount"),\n    ("source", "Источник приобретения", "fa-hand-holding-dollar", "amount"),\n]\n\n# Buckets: (upper limit, name). A value goes into the first bucket whose limit it is under.\nAGE_GROUPS = [(4, "до 3 лет"), (8, "4–7 лет"), (13, "8–12 лет"), (21, "13–20 лет"), (999, "старше 20 лет")]\nAREA_GROUPS = [(50, "до 50 м²"), (100, "50–100 м²"), (200, "100–200 м²"), (500, "200–500 м²"),\n               (1000, "500–1 000 м²"), (10**12, "больше 1 000 м²")]\nSIZE_GROUPS = [(50e6, "до 50 млн"), (100e6, "50–100 млн"), (300e6, "100–300 млн"),\n               (1e9, "300 млн – 1 млрд"), (5e9, "1–5 млрд"), (1e18, "больше 5 млрд")]\nTERM_GROUPS = [(0, "истёк"), (31, "до 30 дней"), (91, "31–90 дней"), (366, "91–365 дней"),\n               (10**6, "больше года")]\nPASP_GROUPS = [(0, "истёк"), (91, "истекает в 90 дней"), (10**6, "действует")]\n\n\ndef names(groups):\n    """[(4, \'до 3 лет\'), (8, \'4–7 лет\')] → [\'до 3 лет\', \'4–7 лет\']"""\n    return [name for limit, name in groups]\n\n\n# The order of the rows in the cards sorted by "label": buckets go small → big, not A → Z.\nORDER = {\n    "age_group": names(AGE_GROUPS), "area_group": names(AREA_GROUPS),\n    "size_group": names(SIZE_GROUPS), "dep_term": names(TERM_GROUPS),\n    "sec_term": names(TERM_GROUPS), "pasp_state": names(PASP_GROUPS),\n    "built_decade": ["до 1960"],\n}\n\n# The deals list: which columns to show for each kind (column, header).\nLIST_COLUMNS = {\n    "car": [("brand", "Марка"), ("model", "Модель"), ("made_year", "Год"), ("plate", "Госномер")],\n    "property": [("building_kind", "Вид"), ("cadastre_no", "Кадастровый номер"),\n                 ("total_area", "Площадь, м²"), ("rooms", "Комнат"), ("address", "Адрес")],\n    "other": [("subkind", "Вид"), ("title", "Описание")],\n    "all": [("kind", "Вид"), ("title", "Описание")],\n}\n\n# Names of the extra columns made by prepare(), for the deal page and Excel.\nEXTRA_LABELS = {\n    "kind": "Вид обеспечения", "subkind": "Группа", "dealid": "Код сделки обеспечения",\n    "mfo": "МФО", "tobo": "Код ТОБО", "parent_id": "Код анкеты / РНК",\n    "currency": "Код валюты", "currency_name": "Валюта", "amount": "Сумма обеспечения, экв.",\n    "market": "Рыночная стоимость", "subtype": "Подтип обеспечения",\n    "note": "Дополнительная информация", "brand": "Марка (итог)", "model": "Модель (итог)",\n    "age_group": "Возраст автомобиля", "pasp_state": "Техпаспорт", "area_group": "Площадь",\n    "rooms_group": "Комнат", "built_decade": "Год постройки", "size_group": "Сумма залога",\n    "dep_term": "До истечения депозита", "sec_term": "До погашения", "policy_year": "Год полиса",\n    "title": "Описание", "issue": "Проверка данных",\n}\n\n\n# ═══════════════════════════════ 1. SAVE ═══════════════════════════════════════════\n\ndef file_for(day):\n    """datasets/collateral/collateral_2026-10-01.parquet"""\n    return DATA_DIR / f"collateral_{day.isoformat()}.parquet"\n\n\ndef saved_days():\n    """Dates that already have a file, newest first: [{\'day\': date, \'size\': \'12.3 МБ\'}]."""\n    days = []\n    for path in sorted(DATA_DIR.glob("collateral_*.parquet"), reverse=True):\n        try:\n            day = date.fromisoformat(path.stem.replace("collateral_", ""))\n        except ValueError:\n            continue\n        days.append({"day": day, "size": f"{path.stat().st_size / 1e6:.1f} МБ"})\n    return days\n\n\ndef as_text(column):\n    """\n    Any column → text, without surprises:\n    numbers from Oracle (12345 or 12345.0) → \'12345\'; extra spaces removed; \'\', \'-\', \'NULL\' → empty.\n    Text is never turned into a number, so \'01\' and \'AB 0012\' keep their zeros.\n    """\n    if pd.api.types.is_numeric_dtype(column):\n        return column.round().astype("Int64").astype("string")\n    text = column.astype("string").str.strip().str.replace(r"\\s+", " ", regex=True)\n    return text.mask(text.isin(BLANKS))\n\n\ndef save_day(day):\n    """Ask Oracle for the three kinds on `day` and save them as ONE parquet file."""\n    parts = queries.load_day(day)\n    frames = []\n    for kind in ["car", "property", "other"]:        # this order matters: see drop_duplicates\n        part = parts[kind]\n        part["kind"] = kind\n        frames.append(part)\n    table = pd.concat(frames, ignore_index=True)\n\n    # A deal with car AND property parameters is counted once, as the first kind.\n    table = table.drop_duplicates("dealid", keep="first")\n\n    for column in table.columns:\n        if column in ["amount", "market"]:\n            table[column] = pd.to_numeric(table[column], errors="coerce")\n        else:\n            table[column] = as_text(table[column])\n\n    DATA_DIR.mkdir(parents=True, exist_ok=True)\n    table.to_parquet(file_for(day), index=False)\n\n\n# ═══════════════════════════════ 2. READ ═══════════════════════════════════════════\n\n# The last table read, so clicking around the page does not read the file every time.\n# It is read again when the file changes (a new download from Oracle).\nMEMORY = {"key": None, "table": None}\n\n\ndef read_day(day, refresh=False):\n    """The clean table for `day`. Goes to Oracle only if there is no file yet (or refresh)."""\n    path = file_for(day)\n    if refresh or not path.exists():\n        save_day(day)\n    key = (str(path), path.stat().st_mtime)\n    if MEMORY["key"] != key:\n        MEMORY["table"] = prepare(pd.read_parquet(path), day)\n        MEMORY["key"] = key\n    return MEMORY["table"]\n\n\n# ═══════════════════════════════ 3. PREPARE ════════════════════════════════════════\n\ndef to_number(column):\n    """\'1 234,56\' / \'1234.56\' / 1234.56 → 1234.56 ; anything else → empty."""\n    text = column.astype("string").str.replace(r"[\\s\xa0]", "", regex=True)\n    text = text.str.replace(",", ".", regex=False)\n    return pd.to_numeric(text, errors="coerce")\n\n\ndef to_date(column):\n    """Text in any of DATE_FORMATS → a date; anything else → empty."""\n    text = column.astype("string").str.strip()\n    result = pd.Series(pd.NaT, index=column.index, dtype="datetime64[ns]")\n    for fmt in DATE_FORMATS:\n        missing = result.isna() &amp; text.notna()\n        if not missing.any():\n            break\n        result[missing] = pd.to_datetime(text[missing], format=fmt, errors="coerce")\n    return result\n\n\ndef to_year(column, day):\n    """\'2019\' / \'2019.0\' / \'01.01.2019\' → 2019 ; a year outside 1900 … next year → empty."""\n    years = to_number(column)\n    from_dates = to_date(column).dt.year\n    years = years.fillna(from_dates)\n    return years.where((years &gt;= 1900) &amp; (years &lt;= day.year + 1))\n\n\ndef same_spelling(column):\n    """\n    \'CHEVROLET\', \'Chevrolet \', \'chevrolet\' are one brand: all three get the spelling\n    used most often. Empty → EMPTY, so the cards have a «не указано» row.\n    """\n    text = as_text(column)\n    key = text.str.upper()\n    pairs = pd.DataFrame({"key": key, "text": text}).dropna()\n    counts = pairs.groupby(["key", "text"]).size().reset_index(name="n")\n    best = counts.sort_values("n", ascending=False).drop_duplicates("key")\n    return key.map(best.set_index("key")["text"]).fillna(EMPTY)\n\n\ndef bucket(values, groups):\n    """Numbers → bucket names, e.g. 7 years → \'4–7 лет\'. Empty → EMPTY."""\n    result = pd.Series(EMPTY, index=values.index, dtype="object")\n    done = values.isna()\n    for limit, name in groups:\n        here = ~done &amp; (values &lt; limit)\n        result[here] = name\n        done = done | here\n    return result\n\n\ndef year_text(years):\n    """2019.0 → \'2019\' (as text: a number would be printed as \'2 019\' by Django)."""\n    return years.map(lambda y: EMPTY if pd.isna(y) else str(int(y)))\n\n\ndef days_left(dates, day):\n    """How many days from `day` until each date (negative = already past)."""\n    return (dates - pd.Timestamp(day)).dt.days\n\n\ndef first_filled(table, columns):\n    """For each row: the first of `columns` that is not empty."""\n    result = pd.Series(pd.NA, index=table.index, dtype="object")\n    for column in columns:\n        if column in table:\n            result = result.fillna(table[column].mask(table[column] == EMPTY))\n    return result\n\n\ndef prepare(table, day):\n    """The raw text from the file → a table ready for counting. Read top to bottom."""\n    table = table.copy()\n\n    # numbers, dates, years\n    for column in MONEY:\n        if column in table:\n            table[column] = to_number(table[column]) / 100\n    for column in NUMBERS:\n        if column in table:\n            table[column] = to_number(table[column])\n    for column in DATES:\n        if column in table:\n            table[column] = to_date(table[column])\n    for column in YEARS:\n        if column in table:\n            table[column] = to_year(table[column], day)\n\n    # the group of «others»: the first group in queries.OTHERS that has a filled parameter\n    table["subkind"] = pd.Series(pd.NA, index=table.index, dtype="object")\n    for name, params in queries.OTHERS.items():\n        columns = [column for column, label in params.values() if column in table]\n        if columns:\n            has_any = table[columns].notna().any(axis=1)\n            table["subkind"] = table["subkind"].mask(table["subkind"].isna() &amp; has_any, name)\n    table["subkind"] = table["subkind"].map(lambda s: SUBKINDS[s]["label"] if s in SUBKINDS else None)\n    table.loc[table["kind"] != "other", "subkind"] = EMPTY\n    table["subkind"] = table["subkind"].fillna("Без параметров")\n\n    # cars: brand and model («Другое» → the free-text column), age, tech passport\n    for name in ["brand", "model"]:\n        main, other = table.get(name + "_main"), table.get(name + "_other")\n        if main is not None:\n            use_other = main.isna() | main.str.upper().isin(OTHER_WORDS)\n            table[name] = main.mask(use_other, other) if other is not None else main\n    if "made_year" in table:\n        table["age_group"] = bucket(day.year - table["made_year"], AGE_GROUPS)\n        table["made_year"] = year_text(table["made_year"])\n    if "pasp_end" in table:\n        left = days_left(table["pasp_end"], day)\n        table["pasp_state"] = bucket(left, PASP_GROUPS)\n\n    # property: area, rooms, decade\n    if "total_area" in table:\n        table["area_group"] = bucket(table["total_area"], AREA_GROUPS)\n    if "rooms" in table:\n        table["rooms_group"] = table["rooms"].map(\n            lambda r: EMPTY if pd.isna(r) or r &lt;= 0 else ("5 и больше" if r &gt;= 5 else str(int(r))))\n    if "built_year" in table:\n        table["built_decade"] = table["built_year"].map(\n            lambda y: EMPTY if pd.isna(y) else ("до 1960" if y &lt; 1960 else f"{int(y) // 10 * 10}-е"))\n        table["built_year"] = year_text(table["built_year"])\n\n    # others: terms of deposits and securities, year of the policy, equipment year\n    if "dep_end" in table:\n        table["dep_term"] = bucket(days_left(table["dep_end"], day), TERM_GROUPS)\n    if "sec_pay_date" in table:\n        table["sec_term"] = bucket(days_left(table["sec_pay_date"], day), TERM_GROUPS)\n    if "policy_date" in table:\n        table["policy_year"] = year_text(table["policy_date"].dt.year)\n    if "eq_year" in table:\n        table["eq_year"] = year_text(table["eq_year"])\n\n    # every page: size of the collateral, currency name\n    table["size_group"] = bucket(table["amount"], SIZE_GROUPS)\n    codes = CODES["currency"]\n    table["currency_name"] = table["currency"].map(lambda c: codes.get(c, c) if pd.notna(c) else EMPTY)\n    for column, names in CODES.items():\n        if column != "currency" and column in table:\n            table[column] = table[column].map(lambda c: names.get(c, c) if pd.notna(c) else c)\n\n    # every column a card groups by: one spelling, EMPTY for blanks\n    for column, title, icon, order in all_cards():\n        if column in table and column not in ["kind", "subkind"]:\n            table[column] = same_spelling(table[column])\n\n    # a short description for the deals list (after the spelling merge: «Chevrolet», not «CHEVROLET»)\n    table["title"] = first_filled(table, [\n        "eq_name", "dep_name", "sec_name", "goods_name", "rights_asset", "rights_object",\n        "policy_no", "land_cadastre_no", "brand", "building_kind", "note"])\n    if "model" in table:                                   # cars: «Chevrolet Malibu»\n        car = (table["kind"] == "car") &amp; (table["model"] != EMPTY)\n        table.loc[car, "title"] = table.loc[car, "brand"] + " " + table.loc[car, "model"]\n    table["kind_name"] = table["kind"].map(lambda k: KINDS[k]["label"])\n\n    # the checks («Проверка данных»): one True/False column per check\n    for code, (label, rows) in find_problems(table, day).items():\n        table["problem_" + code] = rows.fillna(False).astype(bool)\n    return table\n\n\ndef find_problems(t, day):\n    """\n    The data checks: code → (what is wrong, which rows). Add your own here — it appears\n    on the page and becomes a filter by itself.\n    """\n    today = pd.Timestamp(day)\n    car, prop, other = t["kind"] == "car", t["kind"] == "property", t["kind"] == "other"\n\n    def has(column):\n        """True where the column is filled (and False everywhere if it does not exist)."""\n        if column not in t:\n            return pd.Series(False, index=t.index)\n        return t[column].notna() &amp; (t[column] != EMPTY)\n\n    def before_day(column):\n        """True where the date in the column is already in the past."""\n        if column not in t:\n            return pd.Series(False, index=t.index)\n        return t[column] &lt; today\n\n    return {\n        "no_market":    ("Нет рыночной стоимости", t["market"].isna() | (t["market"] &lt;= 0)),\n        "over_market":  ("Сумма залога больше рыночной стоимости", t["amount"] &gt; t["market"]),\n        "no_parent":    ("Не привязан к анкете / РНК", t["parent_id"].isna()),\n        "car_no_plate": ("Авто без госномера", car &amp; ~has("plate")),\n        "car_no_year":  ("Авто без года выпуска", car &amp; ~has("made_year")),\n        "car_pasp_old": ("Техпаспорт просрочен", car &amp; before_day("pasp_end")),\n        "prop_no_cad":  ("Недвижимость без кадастрового номера", prop &amp; ~has("cadastre_no")),\n        "prop_no_area": ("Недвижимость без площади", prop &amp; ~(t.get("total_area", pd.Series(0, index=t.index)) &gt; 0)),\n        "dep_expired":  ("Депозит в залоге уже истёк", other &amp; before_day("dep_end")),\n        "sec_expired":  ("Ценная бумага уже погашена", other &amp; before_day("sec_pay_date")),\n    }\n\n\ndef all_cards():\n    """Every card of every page (used to know which columns to clean)."""\n    cards = CARS_CARDS + PROPERTY_CARDS + OTHERS_CARDS + COMMON_CARDS\n    for extra in SUBKIND_CARDS.values():\n        cards = cards + extra\n    return cards\n\n\n# ═══════════════════════════════ 4. COUNT ══════════════════════════════════════════\n\ndef number(x, digits=0):\n    """1234567.891 → \'1 234 568\' (digits=0) or \'1 234 567,9\' (digits=1). Empty → \'—\'."""\n    if x is None or pd.isna(x):\n        return "—"\n    text = f"{x:,.{digits}f}"\n    return text.replace(",", "\xa0").replace(".", ",")\n\n\ndef mln(x):\n    """Money in millions: 1 234 567 890 → \'1 234,6\'."""\n    return number(x / 1e6, 1) if x is not None and not pd.isna(x) else "—"\n\n\ndef percent(part, whole):\n    return round(part / whole * 100, 1) if whole else 0\n\n\ndef filter_keys():\n    """Every word allowed as a filter in the address (?brand=…&amp;made_year=…)."""\n    keys = {"kind", "issue"}\n    for column, title, icon, order in all_cards():\n        keys.add(column)\n    return keys\n\n\ndef apply_filters(table, filters):\n    """Keep only the rows that match every (column, value) in `filters`."""\n    for column, value in filters:\n        if column == "issue":\n            if "problem_" + value in table:\n                table = table[table["problem_" + value]]\n        elif column in table:\n            table = table[table[column] == value]\n    return table\n\n\ndef cards_for(filters):\n    """Which cards a page shows, depending on what is already chosen."""\n    chosen = dict(filters)\n    kind = chosen.get("kind")\n    if kind == "car":\n        cards = CARS_CARDS\n    elif kind == "property":\n        cards = PROPERTY_CARDS\n    elif kind == "other":\n        cards = OTHERS_CARDS\n        for key, info in SUBKINDS.items():\n            if chosen.get("subkind") == info["label"]:\n                cards = cards + SUBKIND_CARDS.get(key, [])\n    else:\n        cards = []\n    return cards + COMMON_CARDS\n\n\ndef make_card(part, column, title, icon, order, filters):\n    """\n    One breakdown card: the rows of `part` grouped by `column`, each row with count, sum,\n    share of the sum and the bar width. Returns None if the column does not exist.\n    """\n    if column not in part:\n        return None\n    groups = part.groupby(column).agg(count=("dealid", "size"), amount=("amount", "sum"))\n    groups = groups.reset_index()\n    total = part["amount"].sum()\n\n    if order == "label":\n        known = ORDER.get(column, [])\n        groups["empty"] = groups[column] == EMPTY        # «не указано» always at the bottom\n        groups["place"] = groups[column].map(lambda v: known.index(v) if v in known else len(known))\n        groups = groups.sort_values(["empty", "place", column])\n        shown, rest = groups.head(40), groups.iloc[40:]\n    else:\n        groups = groups.sort_values("amount", ascending=False)\n        shown, rest = groups.head(TOP), groups.iloc[TOP:]\n\n    chosen = dict(filters)\n    biggest = shown["amount"].max() if len(shown) else 0\n    rows = []\n    for _, g in shown.iterrows():\n        rows.append({\n            "label": g[column],\n            "value": g[column],\n            "count": number(g["count"]),\n            "amount": mln(g["amount"]),\n            "share": number(percent(g["amount"], total), 1),\n            "width": percent(g["amount"], biggest) if biggest else 0,\n            "active": chosen.get(column) == g[column],\n            "empty": g[column] == EMPTY,\n        })\n    card = {"column": column, "title": title, "icon": icon, "rows": rows,\n            "clickable": column not in chosen,\n            "nothing": len(rows) == 1 and rows[0]["empty"]}\n    if len(rest):\n        card["rest"] = {"n": len(rest), "count": number(rest["count"].sum()),\n                        "amount": mln(rest["amount"].sum()),\n                        "share": number(percent(rest["amount"].sum(), total), 1)}\n    return card\n\n\ndef kind_tiles(part):\n    """The three big tiles on the first page: cars / property / other."""\n    total = part["amount"].sum()\n    tiles = []\n    for key, info in KINDS.items():\n        rows = part[part["kind"] == key]\n        tiles.append({"key": key, "label": info["label"], "icon": info["icon"],\n                      "count": number(len(rows)), "amount": mln(rows["amount"].sum()),\n                      "market": mln(rows["market"].sum()),\n                      "share": number(percent(rows["amount"].sum(), total), 1),\n                      "width": percent(rows["amount"].sum(), total)})\n    return tiles\n\n\ndef subkind_tiles(part):\n    """Small tiles for the groups of «others»."""\n    tiles = []\n    for key, info in SUBKINDS.items():\n        rows = part[part["subkind"] == info["label"]]\n        if len(rows):\n            tiles.append({"label": info["label"], "icon": info["icon"],\n                          "count": number(len(rows)), "amount": mln(rows["amount"].sum())})\n    return tiles\n\n\ndef kpis(part, kind, day):\n    """The numbers at the top: [{\'label\', \'value\', \'note\', \'icon\', \'bad\'}]."""\n    amount, market = part["amount"].sum(), part["market"].sum()\n    out = [\n        {"label": "Сделок обеспечения", "value": number(len(part)), "icon": "fa-file-signature",\n         "note": "строк на дату"},\n        {"label": "Сумма залога", "value": mln(amount), "icon": "fa-scale-balanced",\n         "note": "млн сум, эквивалент"},\n        {"label": "Рыночная стоимость", "value": mln(market), "icon": "fa-tags",\n         "note": "млн сум"},\n        {"label": "Залог / рынок", "value": number(percent(amount, market), 1) + " %",\n         "icon": "fa-percent", "note": "сколько от рыночной цены принято в залог"},\n        {"label": "Средний залог", "value": mln(amount / len(part)) if len(part) else "—",\n         "icon": "fa-equals", "note": "млн сум на сделку"},\n    ]\n    if kind == "car" and "made_year" in part:\n        years = pd.to_numeric(part["made_year"], errors="coerce")\n        ages = day.year - years\n        old = (ages &gt; 10).sum()\n        out.append({"label": "Средний возраст", "value": number(ages.mean(), 1) + " г.",\n                    "icon": "fa-hourglass-half", "note": f"старше 10 лет: {number(old)}"})\n        if "mileage" in part:\n            out.append({"label": "Средний пробег", "value": number(part["mileage"].mean()),\n                        "icon": "fa-road", "note": "км"})\n        bad = int(part["problem_car_pasp_old"].sum())\n        out.append({"label": "Техпаспорт просрочен", "value": number(bad), "icon": "fa-id-card",\n                    "note": "на выбранную дату", "bad": bad &gt; 0})\n    if kind == "property" and "total_area" in part:\n        area = part["total_area"].sum()\n        both = part[(part["total_area"] &gt; 0) &amp; (part["market"] &gt; 0)]\n        per_m2 = both["market"].sum() / both["total_area"].sum() if len(both) else None\n        out.append({"label": "Общая площадь", "value": number(area), "icon": "fa-ruler-combined",\n                    "note": "м²"})\n        out.append({"label": "Цена за м²", "value": number(per_m2), "icon": "fa-house",\n                    "note": "сум, рыночная стоимость / площадь"})\n        if "cadastre_value" in part:\n            out.append({"label": "Кадастровая стоимость", "value": mln(part["cadastre_value"].sum()),\n                        "icon": "fa-landmark", "note": "млн сум"})\n    if kind == "other":\n        if "dep_end" in part:\n            soon = part["dep_term"].isin(["истёк", "до 30 дней"]).sum()\n            out.append({"label": "Депозиты: истекают", "value": number(soon), "icon": "fa-piggy-bank",\n                        "note": "истёк или до 30 дней", "bad": soon &gt; 0})\n        if "jewel_weight" in part and part["jewel_weight"].notna().any():\n            out.append({"label": "Вес ювелирных изделий", "value": number(part["jewel_weight"].sum(), 1),\n                        "icon": "fa-gem", "note": "сумма по полю «Вес»"})\n        if "harvest_crop_area" in part and part["harvest_crop_area"].notna().any():\n            out.append({"label": "Посевная площадь", "value": number(part["harvest_crop_area"].sum(), 1),\n                        "icon": "fa-wheat-awn", "note": "га, будущий урожай"})\n    return out\n\n\ndef problems(part):\n    """The «Проверка данных» list for the rows on the page."""\n    out = []\n    labels = find_problems_labels()\n    for code, label in labels.items():\n        n = int(part["problem_" + code].sum()) if "problem_" + code in part else 0\n        if n:\n            out.append({"code": code, "label": label, "count": number(n),\n                        "share": number(percent(n, len(part)), 1)})\n    return out\n\n\ndef find_problems_labels():\n    """code → label of every check, without computing them (an empty table is enough)."""\n    empty = pd.DataFrame({"kind": [], "market": [], "amount": [], "parent_id": []})\n    return {code: label for code, (label, rows) in find_problems(empty, date.today()).items()}\n\n\ndef deal_list(part, kind, page):\n    """One page of the deals list, biggest first."""\n    columns = [(c, h) for c, h in LIST_COLUMNS.get(kind or "all", []) if c in part]\n    part = part.sort_values("amount", ascending=False)\n    pages = max(1, -(-len(part) // PAGE_SIZE))          # rounded up\n    page = min(max(1, page), pages)\n    rows = []\n    for _, r in part.iloc[(page - 1) * PAGE_SIZE: page * PAGE_SIZE].iterrows():\n        cells = []\n        for column, header in columns:\n            value = r[column]\n            if column == "kind":\n                value = KINDS[value]["label"]\n            elif isinstance(value, numbers.Number) and not pd.isna(value):\n                value = number(value, 1 if value % 1 else 0)\n            cells.append("—" if value is None or (not isinstance(value, str) and pd.isna(value)) else value)\n        rows.append({"dealid": r["dealid"], "mfo": r["mfo"] if pd.notna(r["mfo"]) else "—",\n                     "cells": cells, "amount": number(r["amount"]),\n                     "market": number(r["market"]),\n                     "warn": bool(pd.notna(r["market"]) and r["amount"] &gt; r["market"])})\n    return {"headers": [h for c, h in columns], "rows": rows, "page": page, "pages": pages,\n            "total": number(len(part))}\n\n\ndef build_page(table, day, filters, page=1):\n    """Everything the page shows for the chosen date and filters."""\n    part = apply_filters(table, filters)\n    kind = dict(filters).get("kind")\n    cards = []\n    for column, title, icon, order in cards_for(filters):\n        card = make_card(part, column, title, icon, order, filters)\n        if card:\n            cards.append(card)\n    context = {\n        "kind": kind,\n        "kind_info": KINDS.get(kind),\n        "kpis": kpis(part, kind, day),\n        "cards": cards,\n        "problems": problems(part),\n        "deals": deal_list(part, kind, page),\n        "empty": len(part) == 0,\n    }\n    if not kind:\n        context["tiles"] = kind_tiles(part)\n    if kind == "other" and "subkind" not in dict(filters):\n        context["subtiles"] = subkind_tiles(part)\n    for info in SUBKINDS.values():                      # a group of «others» is open\n        if dict(filters).get("subkind") == info["label"]:\n            context["kind_info"] = info\n    return context\n\n\ndef filter_label(column, value):\n    """What a chosen filter is called in the breadcrumbs: (\'Марка\', \'Chevrolet\')."""\n    if column == "kind":\n        return "Вид", KINDS.get(value, {}).get("label", value)\n    if column == "issue":\n        return "Проверка", find_problems_labels().get(value, value)\n    for c, title, icon, order in all_cards():\n        if c == column:\n            return title, value\n    return column, value\n\n\n# ═══════════════════════════════ 5. ONE DEAL, EXCEL ════════════════════════════════\n\ndef labels():\n    """column → Russian name, for every column that may be in the table."""\n    return {**EXTRA_LABELS, **queries.all_labels()}\n\n\ndef show(value):\n    """One value as text for the deal page and Excel."""\n    if value is None or (not isinstance(value, str) and pd.isna(value)):\n        return None\n    if isinstance(value, pd.Timestamp):\n        return value.strftime("%d.%m.%Y")\n    if isinstance(value, numbers.Number):\n        return number(value, 2 if value % 1 else 0)\n    if value == EMPTY:\n        return None\n    return str(value)\n\n\ndef deal_card(table, dealid):\n    """All filled fields of one deal, in sections: [{\'title\', \'rows\': [(label, value)]}]."""\n    rows = table[table["dealid"] == dealid]\n    if rows.empty:\n        return None\n    r = rows.iloc[0]\n    names = labels()\n    main = ["kind_name", "subkind", "dealid", "mfo", "tobo", "parent_id", "currency_name",\n            "amount", "market", "subtype", "source", "note"]\n    names["kind_name"] = "Вид обеспечения"\n    sections = [{"title": "Основное", "icon": "fa-circle-info",\n                 "rows": [(names.get(c, c), show(r.get(c))) for c in main if show(r.get(c))]}]\n    params = {"car": queries.CARS, "property": queries.PROPERTY}.get(r["kind"], queries.others_flat())\n    filled = [(label, show(r.get(column))) for column, label in params.values() if show(r.get(column))]\n    sections.append({"title": "Параметры", "icon": "fa-list", "rows": filled})\n    issues = [label for code, label in find_problems_labels().items() if r.get("problem_" + code)]\n    return {"dealid": dealid, "kind": KINDS[r["kind"]], "title": show(r.get("title")),\n            "amount": number(r["amount"]), "market": number(r["market"]),\n            "sections": sections, "issues": issues}\n\n\ndef excel_table(table, filters):\n    """The filtered rows with Russian headers, only the columns that have something in them."""\n    part = apply_filters(table, filters).sort_values("amount", ascending=False)\n    names = labels()\n    skip = {"title", "kind_name"} | {c for c in part.columns if c.startswith("problem_")}\n    columns = [c for c in part.columns if c not in skip and part[c].notna().any()\n               and not (part[c] == EMPTY).all()]\n    out = part[columns].copy()\n    for c in columns:\n        if pd.api.types.is_datetime64_any_dtype(out[c]):\n            out[c] = out[c].dt.date\n        elif out[c].dtype == object or str(out[c].dtype) == "string":\n            out[c] = out[c].replace(EMPTY, None)\n    out["kind"] = out["kind"].map(lambda k: KINDS[k]["label"])\n    return out.rename(columns=names)\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-7. views.py', 'category': 'programming', 'order': 7, 'summary': 'The views: each reads the address, asks process.py, renders a template.', 'content': '<p>Step 7 of 12. Save as <code>collateral/views.py</code>.</p>\n<h3>views.py</h3>\n<pre><code class="language-python">"""\nThe pages of the collateral app. Every view is short: it reads the address, asks\nprocess.py for the numbers and gives them to a template.\n\nHOW THE DRILL-DOWN WORKS (no JavaScript)\nEvery choice is a word in the address:\n\n    /collateral/?date=2026-10-01                                  everything\n    /collateral/?date=2026-10-01&amp;kind=car                         only cars\n    /collateral/?date=2026-10-01&amp;kind=car&amp;brand=Chevrolet         only Chevrolets\n    /collateral/?date=2026-10-01&amp;kind=car&amp;brand=Chevrolet&amp;made_year=2019\n\nA click on a row of a card adds one more word; a click on a breadcrumb removes the words\nafter it. So every view of the data has its own link: send it to a colleague and they\nsee the same thing.\n"""\nfrom datetime import datetime\nfrom urllib.parse import urlencode\n\nfrom django.http import FileResponse, Http404, HttpResponse\nfrom django.shortcuts import render\n\nfrom . import process, queries\nfrom .forms import DayForm\n\n\ndef read_filters(request):\n    """The filters from the address, in the order they were chosen: [(\'kind\', \'car\'), ...]."""\n    allowed = process.filter_keys()\n    filters = []\n    for key, value in request.GET.items():\n        if key in allowed and value and key not in dict(filters):\n            filters.append((key, value))\n    return filters\n\n\ndef page_number(request):\n    """?page=3 → 3; anything else → 1."""\n    text = request.GET.get("page", "1")\n    return int(text) if text.isdigit() else 1\n\n\ndef address(day, filters):\n    """The part of the link after \'?\': date=2026-10-01&amp;kind=car&amp;brand=Chevrolet"""\n    return urlencode([("date", day.isoformat())] + list(filters))\n\n\ndef breadcrumbs(day, filters):\n    """«Всё обеспечение › Автотранспорт › Chevrolet»: each crumb links to the filters up to it."""\n    crumbs = [{"title": "", "label": "Всё обеспечение", "link": address(day, [])}]\n    for n, (column, value) in enumerate(filters, start=1):\n        title, label = process.filter_label(column, value)\n        crumbs.append({"title": title, "label": label, "link": address(day, filters[:n])})\n    return crumbs\n\n\ndef home(request):\n    """The main page: the date form, then the numbers for the date and the chosen filters."""\n    form = DayForm(request.GET or None)\n    context = {"form": form, "saved": process.saved_days()}\n    if not form.is_valid():\n        return render(request, "collateral/page.html", context)\n\n    day = form.cleaned_data["date"]\n    try:\n        table = process.read_day(day, refresh=form.cleaned_data["refresh"])\n    except Exception as error:          # no database, wrong table name, no pyarrow ...\n        context["error"] = f"Не удалось загрузить данные на {day:%d.%m.%Y}: {error}"\n        return render(request, "collateral/page.html", context)\n\n    filters = read_filters(request)\n    context.update(process.build_page(table, day, filters, page_number(request)))\n    context.update({\n        "day": day,\n        "filters": filters,\n        "link": address(day, filters),          # the current view, to add one more filter\n        "crumbs": breadcrumbs(day, filters),\n        "saved_at": datetime.fromtimestamp(process.file_for(day).stat().st_mtime),\n    })\n    return render(request, "collateral/page.html", context)\n\n\ndef deal(request, dealid):\n    """Every filled field of one collateral deal."""\n    form = DayForm(request.GET)\n    if not form.is_valid():\n        raise Http404("Нет даты")\n    day = form.cleaned_data["date"]\n    if not process.file_for(day).exists():\n        raise Http404("На эту дату данные ещё не загружены")\n    card = process.deal_card(process.read_day(day), dealid)\n    if card is None:\n        raise Http404("Такой сделки обеспечения нет на эту дату")\n    filters = read_filters(request)\n    return render(request, "collateral/deal.html", {\n        "day": day, "card": card, "back": address(day, filters)})\n\n\ndef excel(request):\n    """The rows of the current view as an .xlsx file (all of them, not one page)."""\n    form = DayForm(request.GET)\n    if not form.is_valid():\n        raise Http404("Нет даты")\n    day = form.cleaned_data["date"]\n    table = process.excel_table(process.read_day(day), read_filters(request))\n    response = HttpResponse(\n        content_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")\n    response["Content-Disposition"] = f\'attachment; filename="collateral_{day.isoformat()}.xlsx"\'\n    table.to_excel(response, index=False, sheet_name="Обеспечение")\n    return response\n\n\ndef parquet_file(request):\n    """The saved parquet file of a date, as a download."""\n    form = DayForm(request.GET)\n    if not form.is_valid() or not process.file_for(form.cleaned_data["date"]).exists():\n        raise Http404("Файла на эту дату нет")\n    path = process.file_for(form.cleaned_data["date"])\n    return FileResponse(open(path, "rb"), as_attachment=True, filename=path.name)\n\n\ndef params(request):\n    """\n    Help page: every parameter that exists in the database on a date (live query),\n    which of them the app already uses, and the finished SQL to copy into your SQL tool.\n    """\n    form = DayForm(request.GET or None)\n    used = {}\n    for kind, params_of_kind in [("Авто", queries.CARS), ("Недвижимость", queries.PROPERTY),\n                                 ("Прочее", queries.others_flat()), ("Общие", queries.COMMON)]:\n        for name, (column, label) in params_of_kind.items():\n            used[name] = f"{kind}: {column}"\n    context = {"form": form, "sql": [("Авто", queries.SQL_CARS),\n                                     ("Недвижимость", queries.SQL_PROPERTY),\n                                     ("Прочее", queries.SQL_OTHERS),\n                                     ("Все параметры на дату", queries.SQL_PARAM_NAMES)]}\n    if form.is_valid():\n        try:\n            names = queries.load_param_names(form.cleaned_data["date"])\n            context["names"] = [{"name": r.paramname, "deals": process.number(r.deals),\n                                 "example": r.example, "used": used.get(r.paramname)}\n                                for r in names.itertuples()]\n        except Exception as error:\n            context["error"] = f"Не удалось выполнить запрос: {error}"\n    return render(request, "collateral/params.html", context)\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-8. templates/collateral/style.html', 'category': 'programming', 'order': 8, 'summary': 'The look (Kapitalbank colours), shared by all pages.', 'content': '<p>Step 8 of 12. Save as <code>collateral/templates/collateral/style.html</code>.</p>\n<h3>templates/collateral/style.html</h3>\n<pre><code class="language-html">{% comment %}\n  The look of the collateral pages, shared by page.html, deal.html and params.html.\n  Kapitalbank colours: yellow leads, charcoal second, red only for problems.\n  Everything sits under .clt so it never touches the rest of the site.\n{% endcomment %}\n&lt;style&gt;\n  .clt{--ink:#0B0B0C;--soft:#2A2A2E;--gold:#F2C230;--gd:#C9971A;--gtext:#8C6A12;\n           --rule:#E4E1D8;--paper:#FAF8F2;--muted:#8A867C;--bad:#B3341F;\n           color:var(--ink)}\n  .clt a{color:inherit}\n  .clt .hero{background:var(--ink);color:#fff;border-radius:12px;padding:22px 26px;margin-bottom:20px}\n  .clt .hero .eyebrow{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold)}\n  .clt .hero h1{font-weight:500;font-size:26px;margin:6px 0 10px}\n  .clt .hero h1 i{color:var(--gold);margin-right:10px}\n  .clt .crumbs{font-size:13px;color:#B9B5AB}\n  .clt .crumbs a{color:#fff;text-decoration:none;border-bottom:1px dotted #777}\n  .clt .crumbs .t{color:#8A867C;font-size:11px;margin-right:3px}\n  .clt .crumbs .sep{margin:0 8px;color:var(--gold)}\n  .clt .btn-go{background:var(--gold);border:none;color:var(--ink);font-weight:600}\n  .clt .btn-go:hover{background:var(--gd);color:var(--ink)}\n  .clt .box{background:#fff;border:1px solid var(--rule);border-radius:12px;margin-bottom:20px}\n  .clt .box-head{background:var(--paper);border-bottom:1px solid var(--rule);border-radius:12px 12px 0 0;\n       padding:10px 16px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--gtext);\n       display:flex;justify-content:space-between;align-items:center;gap:8px}\n  .clt .box-head i{margin-right:8px;color:var(--gd)}\n  .clt .box-head .hint{letter-spacing:0;text-transform:none;color:var(--muted);font-size:12px}\n  .clt .kpi{background:#fff;border:1px solid var(--rule);border-radius:12px;padding:12px 14px;height:100%}\n  .clt .kpi .l{font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}\n  .clt .kpi .l i{color:var(--gd);margin-right:6px}\n  .clt .kpi .v{font-size:21px;font-weight:600;margin-top:4px;white-space:nowrap}\n  .clt .kpi .n{font-size:12px;color:var(--muted)}\n  .clt .kpi.bad{border-color:var(--bad)} .clt .kpi.bad .v{color:var(--bad)}\n  /* the three big tiles */\n  .clt .tile{display:block;text-decoration:none;background:#fff;border:1px solid var(--rule);\n       border-radius:14px;padding:18px 20px;height:100%;transition:border-color .15s, box-shadow .15s}\n  .clt .tile:hover{border-color:var(--gold);box-shadow:0 4px 14px rgba(0,0,0,.07)}\n  .clt .tile .ic{width:54px;height:54px;border-radius:50%;background:var(--ink);color:var(--gold);\n       display:flex;align-items:center;justify-content:center;font-size:24px;margin-bottom:12px}\n  .clt .tile .name{font-size:18px;font-weight:600}\n  .clt .tile .big{font-size:24px;font-weight:600;margin-top:6px}\n  .clt .tile .small{font-size:12.5px;color:var(--muted)}\n  .clt .tile .go{font-size:13px;color:var(--gtext);margin-top:10px}\n  .clt .subtile{display:flex;gap:12px;align-items:center;text-decoration:none;background:#fff;\n       border:1px solid var(--rule);border-radius:10px;padding:10px 12px;height:100%}\n  .clt .subtile:hover{border-color:var(--gold)}\n  .clt .subtile i{font-size:20px;color:var(--gd);width:26px;text-align:center}\n  .clt .subtile .name{font-size:13.5px;font-weight:600;line-height:1.2}\n  .clt .subtile .small{font-size:12px;color:var(--muted)}\n  /* the cards */\n  .clt table{font-size:13px;margin:0}\n  .clt th{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);\n       font-weight:600;white-space:nowrap}\n  .clt td.m,.clt th.m{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}\n  .clt td.lab{max-width:240px}\n  .clt td.lab a{text-decoration:none;border-bottom:1px dotted var(--muted)}\n  .clt td.lab a:hover{color:var(--gtext);border-color:var(--gold)}\n  .clt tr.on td{background:#FFF6D6;font-weight:600}\n  .clt .empty-val{color:var(--muted);font-style:italic}\n  .clt .bar-cell{width:28%;min-width:70px}\n  .clt .bar{height:9px;border-radius:3px;background:var(--gold);min-width:2px}\n  .clt .empty-val .bar,.clt tr.rest .bar{background:#D9D5CB}\n  .clt tr.rest td{color:var(--muted)}\n  .clt .nothing{padding:14px 16px;color:var(--muted);font-size:13px}\n  .clt .warn{color:var(--bad)}\n  .clt .problem{display:flex;justify-content:space-between;gap:10px;padding:8px 16px;\n       border-bottom:1px solid var(--rule);text-decoration:none;font-size:13.5px}\n  .clt .problem:last-child{border-bottom:none}\n  .clt .problem:hover{background:#FFF6EE}\n  .clt .problem i{color:var(--bad);margin-right:8px}\n  .clt .chip{display:inline-block;border:1px solid var(--rule);border-radius:20px;padding:3px 12px;\n       font-size:12.5px;text-decoration:none;margin:0 6px 6px 0;background:#fff}\n  .clt .chip:hover{border-color:var(--gold)}\n  .clt .code{font-family:Consolas,monospace;font-size:12px}\n  .clt pre.sql{background:var(--paper);border:1px solid var(--rule);border-radius:8px;padding:12px;\n       font-size:12px;max-height:420px;overflow:auto}\n  @media print{\n    .sb-topnav,#layoutSidenav_nav,.clt .no-print{display:none!important}\n    #layoutSidenav_content{padding-left:0!important;margin-left:0!important}\n    .clt .hero,.clt .bar,.clt .tile .ic{-webkit-print-color-adjust:exact;print-color-adjust:exact}\n    .clt .box,.clt .tile{break-inside:avoid}\n  }\n&lt;/style&gt;\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-9. templates/collateral/card.html', 'category': 'programming', 'order': 9, 'summary': 'One breakdown card: rows are links that add a filter.', 'content': '<p>Step 9 of 12. Save as <code>collateral/templates/collateral/card.html</code>.</p>\n<h3>templates/collateral/card.html</h3>\n<pre><code class="language-html">{% comment %}\n  One breakdown card (included by page.html inside a loop over `cards`).\n  A row is a link that adds this card\'s filter: ?{{ link }}&amp;{{ card.column }}=&lt;value&gt;.\n  When this column is already chosen, the rows are no longer links and the chosen one is lit.\n{% endcomment %}\n&lt;div class="box h-100"&gt;\n  &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid {{ card.icon }}"&gt;&lt;/i&gt;{{ card.title }}&lt;/span&gt;\n    &lt;span class="hint"&gt;шт · млн сум · доля суммы&lt;/span&gt;&lt;/div&gt;\n  {% if card.nothing %}\n  &lt;div class="nothing"&gt;&lt;i class="fa-regular fa-circle-question me-1"&gt;&lt;/i&gt;Поле не заполнено ни в одной сделке.&lt;/div&gt;\n  {% else %}\n  &lt;div class="table-responsive"&gt;\n    &lt;table class="table table-sm align-middle"&gt;\n      &lt;tbody&gt;\n      {% for r in card.rows %}\n        &lt;tr class="{% if r.active %}on{% endif %}{% if r.empty %} empty-val{% endif %}"&gt;\n          &lt;td class="lab"&gt;{% if card.clickable %}&lt;a href="?{{ link }}&amp;{{ card.column }}={{ r.value|urlencode }}"&gt;{{ r.label }}&lt;/a&gt;{% else %}{{ r.label }}{% endif %}&lt;/td&gt;\n          &lt;td class="m"&gt;{{ r.count }}&lt;/td&gt;\n          &lt;td class="m"&gt;{{ r.amount }}&lt;/td&gt;\n          &lt;td class="m text-muted"&gt;{{ r.share }} %&lt;/td&gt;\n          &lt;td class="bar-cell"&gt;&lt;div class="bar" style="width:{{ r.width|stringformat:\'.1f\' }}%"&gt;&lt;/div&gt;&lt;/td&gt;\n        &lt;/tr&gt;\n      {% endfor %}\n      {% if card.rest %}\n        &lt;tr class="rest"&gt;\n          &lt;td class="lab"&gt;Остальные ({{ card.rest.n }})&lt;/td&gt;\n          &lt;td class="m"&gt;{{ card.rest.count }}&lt;/td&gt;\n          &lt;td class="m"&gt;{{ card.rest.amount }}&lt;/td&gt;\n          &lt;td class="m"&gt;{{ card.rest.share }} %&lt;/td&gt;\n          &lt;td&gt;&lt;/td&gt;\n        &lt;/tr&gt;\n      {% endif %}\n      &lt;/tbody&gt;\n    &lt;/table&gt;\n  &lt;/div&gt;\n  {% endif %}\n&lt;/div&gt;\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-10. templates/collateral/page.html', 'category': 'programming', 'order': 10, 'summary': 'The main page: date form, header with breadcrumbs, KPIs, the three tiles, the cards, data checks, the deals list.', 'content': '<p>Step 10 of 12. Save as <code>collateral/templates/collateral/page.html</code>.</p>\n<h3>templates/collateral/page.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% comment %}\n  The collateral page. One template for every level of the drill-down:\n  no kind chosen → three big tiles; a kind chosen → its own cards.\n  Every number arrives already formatted from process.py, so the template only places it.\n  Links: "?{{ link }}&amp;brand=…" = the current view plus one more filter.\n  No JavaScript except the one-line «Печать» button.\n{% endcomment %}\n\n{% block extra_css %}{% include "collateral/style.html" %}{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="clt container-fluid px-4 py-4"&gt;\n\n  {# ── the date form ── #}\n  &lt;div class="box no-print"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-shield-halved"&gt;&lt;/i&gt;Обеспечение банка&lt;/span&gt;\n      &lt;a class="hint" href="{% url \'collateral-params\' %}{% if day %}?date={{ day|date:\'Y-m-d\' }}{% endif %}"&gt;\n        &lt;i class="fa-solid fa-sliders"&gt;&lt;/i&gt;Параметры и SQL&lt;/a&gt;&lt;/div&gt;\n    &lt;div class="p-3"&gt;\n      &lt;form method="get" class="row g-3 align-items-end"&gt;\n        &lt;div class="col-sm-5 col-md-3"&gt;\n          &lt;label class="form-label small text-muted" for="{{ form.date.id_for_label }}"&gt;{{ form.date.label }}&lt;/label&gt;\n          {{ form.date }}\n        &lt;/div&gt;\n        &lt;div class="col-sm-7 col-md-4"&gt;\n          &lt;div class="form-check mb-2"&gt;\n            {{ form.refresh }}\n            &lt;label class="form-check-label small" for="{{ form.refresh.id_for_label }}"&gt;{{ form.refresh.label }}&lt;/label&gt;\n          &lt;/div&gt;\n        &lt;/div&gt;\n        {% for key, value in filters %}&lt;input type="hidden" name="{{ key }}" value="{{ value }}"&gt;{% endfor %}\n        &lt;div class="col-md-3"&gt;\n          &lt;button class="btn btn-go px-4" type="submit"&gt;&lt;i class="fa-solid fa-magnifying-glass me-1"&gt;&lt;/i&gt;Показать&lt;/button&gt;\n        &lt;/div&gt;\n      &lt;/form&gt;\n      {% if saved %}\n      &lt;div class="mt-3 small text-muted"&gt;Уже загружены:&lt;/div&gt;\n      &lt;div class="mt-1"&gt;\n        {% for s in saved|slice:":12" %}\n        &lt;a class="chip" href="?date={{ s.day|date:\'Y-m-d\' }}"&gt;&lt;i class="fa-regular fa-calendar me-1"&gt;&lt;/i&gt;{{ s.day|date:"d.m.Y" }} &lt;span class="text-muted"&gt;· {{ s.size }}&lt;/span&gt;&lt;/a&gt;\n        {% endfor %}\n      &lt;/div&gt;\n      {% else %}\n      &lt;div class="mt-3 small text-muted"&gt;Первый запрос на дату идёт в базу и сохраняется в datasets/collateral/ — следующие открываются из файла.&lt;/div&gt;\n      {% endif %}\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {% if error %}&lt;div class="alert alert-warning"&gt;&lt;i class="fa-solid fa-triangle-exclamation me-2"&gt;&lt;/i&gt;{{ error }}&lt;/div&gt;{% endif %}\n\n  {% if day %}\n  {# ── header: where we are ── #}\n  &lt;div class="hero"&gt;\n    &lt;div class="d-flex flex-wrap justify-content-between align-items-start gap-3"&gt;\n      &lt;div&gt;\n        &lt;div class="eyebrow"&gt;Обеспечение на {{ day|date:"d.m.Y" }}&lt;/div&gt;\n        &lt;h1&gt;{% if kind_info %}&lt;i class="fa-solid {{ kind_info.icon }}"&gt;&lt;/i&gt;{{ kind_info.label }}{% else %}&lt;i class="fa-solid fa-shield-halved"&gt;&lt;/i&gt;Всё обеспечение{% endif %}&lt;/h1&gt;\n        &lt;div class="crumbs"&gt;\n          {% for c in crumbs %}\n            {% if not forloop.first %}&lt;span class="sep"&gt;›&lt;/span&gt;{% endif %}\n            {% if forloop.last %}&lt;span&gt;&lt;span class="t"&gt;{{ c.title }}&lt;/span&gt;{{ c.label }}&lt;/span&gt;\n            {% else %}&lt;a href="?{{ c.link }}"&gt;&lt;span class="t"&gt;{{ c.title }}&lt;/span&gt;{{ c.label }}&lt;/a&gt;{% endif %}\n          {% endfor %}\n        &lt;/div&gt;\n      &lt;/div&gt;\n      &lt;div class="no-print d-flex flex-wrap gap-2"&gt;\n        &lt;a class="btn btn-go btn-sm" href="{% url \'collateral-excel\' %}?{{ link }}"&gt;&lt;i class="fa-solid fa-file-excel me-1"&gt;&lt;/i&gt;Excel&lt;/a&gt;\n        &lt;a class="btn btn-outline-light btn-sm" href="{% url \'collateral-file\' %}?date={{ day|date:\'Y-m-d\' }}"&gt;&lt;i class="fa-solid fa-database me-1"&gt;&lt;/i&gt;Parquet&lt;/a&gt;\n        &lt;button class="btn btn-outline-light btn-sm" type="button" onclick="window.print()"&gt;&lt;i class="fa-solid fa-print me-1"&gt;&lt;/i&gt;Печать&lt;/button&gt;\n      &lt;/div&gt;\n    &lt;/div&gt;\n    &lt;div class="small mt-2" style="color:#8A867C"&gt;Файл сохранён {{ saved_at|date:"d.m.Y H:i" }} · суммы в млн сум, эквивалент&lt;/div&gt;\n  &lt;/div&gt;\n\n  {% if empty %}\n  &lt;div class="alert alert-light border"&gt;На эту дату и с этими фильтрами нет ни одной сделки обеспечения.&lt;/div&gt;\n  {% else %}\n\n  {# ── KPIs ── #}\n  &lt;div class="row g-3 mb-4"&gt;\n    {% for k in kpis %}\n    &lt;div class="col-6 col-md-4 col-xl"&gt;\n      &lt;div class="kpi{% if k.bad %} bad{% endif %}"&gt;\n        &lt;div class="l"&gt;&lt;i class="fa-solid {{ k.icon }}"&gt;&lt;/i&gt;{{ k.label }}&lt;/div&gt;\n        &lt;div class="v"&gt;{{ k.value }}&lt;/div&gt;\n        &lt;div class="n"&gt;{{ k.note }}&lt;/div&gt;\n      &lt;/div&gt;\n    &lt;/div&gt;\n    {% endfor %}\n  &lt;/div&gt;\n\n  {# ── first page: the three kinds ── #}\n  {% if tiles %}\n  &lt;div class="row g-3 mb-4"&gt;\n    {% for t in tiles %}\n    &lt;div class="col-md-4"&gt;\n      &lt;a class="tile" href="?{{ link }}&amp;kind={{ t.key }}"&gt;\n        &lt;div class="ic"&gt;&lt;i class="fa-solid {{ t.icon }}"&gt;&lt;/i&gt;&lt;/div&gt;\n        &lt;div class="name"&gt;{{ t.label }}&lt;/div&gt;\n        &lt;div class="big"&gt;{{ t.amount }} &lt;span class="small"&gt;млн&lt;/span&gt;&lt;/div&gt;\n        &lt;div class="small"&gt;{{ t.count }} сделок · рыночная {{ t.market }} млн&lt;/div&gt;\n        &lt;div class="progress mt-2" style="height:8px"&gt;&lt;div class="progress-bar" style="width:{{ t.width|stringformat:\'.1f\' }}%;background:#F2C230"&gt;&lt;/div&gt;&lt;/div&gt;\n        &lt;div class="small mt-1"&gt;{{ t.share }} % всего залога&lt;/div&gt;\n        &lt;div class="go no-print"&gt;Подробнее &lt;i class="fa-solid fa-arrow-right"&gt;&lt;/i&gt;&lt;/div&gt;\n      &lt;/a&gt;\n    &lt;/div&gt;\n    {% endfor %}\n  &lt;/div&gt;\n  {% endif %}\n\n  {# ── «other»: one tile per group ── #}\n  {% if subtiles %}\n  &lt;div class="row g-2 mb-4"&gt;\n    {% for t in subtiles %}\n    &lt;div class="col-6 col-md-4 col-xl-3"&gt;\n      &lt;a class="subtile" href="?{{ link }}&amp;subkind={{ t.label|urlencode }}"&gt;\n        &lt;i class="fa-solid {{ t.icon }}"&gt;&lt;/i&gt;\n        &lt;div&gt;&lt;div class="name"&gt;{{ t.label }}&lt;/div&gt;\n          &lt;div class="small"&gt;{{ t.count }} шт · {{ t.amount }} млн&lt;/div&gt;&lt;/div&gt;\n      &lt;/a&gt;\n    &lt;/div&gt;\n    {% endfor %}\n  &lt;/div&gt;\n  {% endif %}\n\n  {# ── the cards: one breakdown each ── #}\n  &lt;div class="row g-3"&gt;\n    {% for card in cards %}\n    &lt;div class="col-lg-6"&gt;{% include "collateral/card.html" %}&lt;/div&gt;\n    {% endfor %}\n\n    {# ── data checks ── #}\n    {% if problems %}\n    &lt;div class="col-lg-6"&gt;\n      &lt;div class="box"&gt;\n        &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-triangle-exclamation"&gt;&lt;/i&gt;Проверка данных&lt;/span&gt;\n          &lt;span class="hint"&gt;нажмите, чтобы увидеть сделки&lt;/span&gt;&lt;/div&gt;\n        {% for p in problems %}\n        &lt;a class="problem" href="?{{ link }}&amp;issue={{ p.code }}"&gt;\n          &lt;span&gt;&lt;i class="fa-solid fa-circle-exclamation"&gt;&lt;/i&gt;{{ p.label }}&lt;/span&gt;\n          &lt;span class="text-nowrap"&gt;&lt;strong&gt;{{ p.count }}&lt;/strong&gt; &lt;span class="text-muted"&gt;· {{ p.share }} %&lt;/span&gt;&lt;/span&gt;\n        &lt;/a&gt;\n        {% endfor %}\n      &lt;/div&gt;\n    &lt;/div&gt;\n    {% endif %}\n  &lt;/div&gt;\n\n  {# ── the deals ── #}\n  &lt;div class="box mt-2"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-list"&gt;&lt;/i&gt;Сделки обеспечения&lt;/span&gt;\n      &lt;span class="hint"&gt;{{ deals.total }} строк · по убыванию суммы · сум&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="table-responsive"&gt;\n      &lt;table class="table table-sm table-hover align-middle"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Код сделки&lt;/th&gt;&lt;th&gt;МФО&lt;/th&gt;{% for h in deals.headers %}&lt;th&gt;{{ h }}&lt;/th&gt;{% endfor %}\n          &lt;th class="m"&gt;Сумма залога&lt;/th&gt;&lt;th class="m"&gt;Рыночная&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;\n        {% for r in deals.rows %}\n          &lt;tr&gt;\n            &lt;td class="code"&gt;&lt;a href="{% url \'collateral-deal\' r.dealid %}?{{ link }}"&gt;{{ r.dealid }}&lt;/a&gt;&lt;/td&gt;\n            &lt;td class="code"&gt;{{ r.mfo }}&lt;/td&gt;\n            {% for c in r.cells %}&lt;td&gt;{{ c }}&lt;/td&gt;{% endfor %}\n            &lt;td class="m{% if r.warn %} warn{% endif %}"&gt;{{ r.amount }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ r.market }}&lt;/td&gt;\n          &lt;/tr&gt;\n        {% endfor %}\n        &lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n    {% if deals.pages &gt; 1 %}\n    &lt;div class="d-flex justify-content-between align-items-center px-3 py-2 no-print small"&gt;\n      {% if deals.page &gt; 1 %}&lt;a href="?{{ link }}&amp;page={{ deals.page|add:\'-1\' }}"&gt;&lt;i class="fa-solid fa-chevron-left me-1"&gt;&lt;/i&gt;Назад&lt;/a&gt;{% else %}&lt;span&gt;&lt;/span&gt;{% endif %}\n      &lt;span class="text-muted"&gt;страница {{ deals.page }} из {{ deals.pages }}&lt;/span&gt;\n      {% if deals.page &lt; deals.pages %}&lt;a href="?{{ link }}&amp;page={{ deals.page|add:\'1\' }}"&gt;Дальше&lt;i class="fa-solid fa-chevron-right ms-1"&gt;&lt;/i&gt;&lt;/a&gt;{% else %}&lt;span&gt;&lt;/span&gt;{% endif %}\n    &lt;/div&gt;\n    {% endif %}\n  &lt;/div&gt;\n\n  {% endif %}{# not empty #}\n  {% endif %}{# day #}\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-11. templates/collateral/deal.html', 'category': 'programming', 'order': 11, 'summary': 'One collateral deal with every filled field.', 'content': '<p>Step 11 of 12. Save as <code>collateral/templates/collateral/deal.html</code>.</p>\n<h3>templates/collateral/deal.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% comment %}\n  One collateral deal: every field that has a value, in two blocks (main, parameters).\n  «Назад» returns to the exact view the deal was opened from.\n{% endcomment %}\n\n{% block extra_css %}{% include "collateral/style.html" %}{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="clt container-fluid px-4 py-4"&gt;\n  &lt;div class="hero"&gt;\n    &lt;div class="eyebrow"&gt;Сделка обеспечения на {{ day|date:"d.m.Y" }}&lt;/div&gt;\n    &lt;h1&gt;&lt;i class="fa-solid {{ card.kind.icon }}"&gt;&lt;/i&gt;{{ card.title|default:card.kind.label }}&lt;/h1&gt;\n    &lt;div class="crumbs"&gt;\n      &lt;a class="no-print" href="{% url \'collateral\' %}?{{ back }}"&gt;&lt;i class="fa-solid fa-arrow-left me-1"&gt;&lt;/i&gt;Назад к списку&lt;/a&gt;\n      &lt;span class="sep"&gt;·&lt;/span&gt;{{ card.kind.label }} · код {{ card.dealid }}\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  &lt;div class="row g-3 mb-4"&gt;\n    &lt;div class="col-6 col-md-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-scale-balanced"&gt;&lt;/i&gt;Сумма залога&lt;/div&gt;\n      &lt;div class="v"&gt;{{ card.amount }}&lt;/div&gt;&lt;div class="n"&gt;сум, эквивалент&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n    &lt;div class="col-6 col-md-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-tags"&gt;&lt;/i&gt;Рыночная стоимость&lt;/div&gt;\n      &lt;div class="v"&gt;{{ card.market }}&lt;/div&gt;&lt;div class="n"&gt;сум&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n  &lt;/div&gt;\n\n  {% if card.issues %}\n  &lt;div class="alert alert-warning"&gt;\n    &lt;i class="fa-solid fa-triangle-exclamation me-2"&gt;&lt;/i&gt;&lt;strong&gt;Проверка данных:&lt;/strong&gt;\n    {% for i in card.issues %}{{ i }}{% if not forloop.last %}; {% endif %}{% endfor %}\n  &lt;/div&gt;\n  {% endif %}\n\n  &lt;div class="row g-3"&gt;\n    {% for s in card.sections %}\n    &lt;div class="col-lg-6"&gt;\n      &lt;div class="box"&gt;\n        &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid {{ s.icon }}"&gt;&lt;/i&gt;{{ s.title }}&lt;/span&gt;&lt;/div&gt;\n        {% if s.rows %}\n        &lt;table class="table table-sm mb-0"&gt;\n          &lt;tbody&gt;\n          {% for label, value in s.rows %}\n            &lt;tr&gt;&lt;td class="text-muted" style="width:45%"&gt;{{ label }}&lt;/td&gt;&lt;td&gt;{{ value }}&lt;/td&gt;&lt;/tr&gt;\n          {% endfor %}\n          &lt;/tbody&gt;\n        &lt;/table&gt;\n        {% else %}\n        &lt;div class="nothing"&gt;Ни одно поле не заполнено.&lt;/div&gt;\n        {% endif %}\n      &lt;/div&gt;\n    &lt;/div&gt;\n    {% endfor %}\n  &lt;/div&gt;\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})

TUTORIALS.append({'title': 'COL-12. templates/collateral/params.html', 'category': 'programming', 'order': 12, 'summary': 'Every parameter name in the database on a date + the finished SQL to copy.', 'content': '<p>Step 12 of 12. Save as <code>collateral/templates/collateral/params.html</code>.</p>\n<h3>templates/collateral/params.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% comment %}\n  Help page for you, not for colleagues:\n  1. every parameter name that exists in the database on a date, and whether the app uses it\n     (this is where you find the address field and add it to queries.PROPERTY);\n  2. the finished SQL of the app, to copy into your SQL tool.\n{% endcomment %}\n\n{% block extra_css %}{% include "collateral/style.html" %}{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="clt container-fluid px-4 py-4"&gt;\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-sliders"&gt;&lt;/i&gt;Параметры обеспечения в базе&lt;/span&gt;\n      &lt;a class="hint" href="{% url \'collateral\' %}"&gt;&lt;i class="fa-solid fa-arrow-left me-1"&gt;&lt;/i&gt;к обеспечению&lt;/a&gt;&lt;/div&gt;\n    &lt;div class="p-3"&gt;\n      &lt;form method="get" class="row g-3 align-items-end"&gt;\n        &lt;div class="col-sm-5 col-md-3"&gt;\n          &lt;label class="form-label small text-muted" for="{{ form.date.id_for_label }}"&gt;{{ form.date.label }}&lt;/label&gt;\n          {{ form.date }}\n        &lt;/div&gt;\n        &lt;div class="col-md-3"&gt;&lt;button class="btn btn-go px-4" type="submit"&gt;Показать параметры&lt;/button&gt;&lt;/div&gt;\n      &lt;/form&gt;\n      &lt;div class="small text-muted mt-2"&gt;Запрос идёт в базу напрямую (без файла) и может занять время.&lt;/div&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {% if error %}&lt;div class="alert alert-warning"&gt;{{ error }}&lt;/div&gt;{% endif %}\n\n  {% if names %}\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-table-list"&gt;&lt;/i&gt;Все параметры на дату&lt;/span&gt;\n      &lt;span class="hint"&gt;{{ names|length }} названий&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="table-responsive"&gt;\n      &lt;table class="table table-sm table-hover align-middle"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th&gt;paramname&lt;/th&gt;&lt;th class="m"&gt;Сделок&lt;/th&gt;&lt;th&gt;Пример значения&lt;/th&gt;&lt;th&gt;В приложении&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;\n        {% for n in names %}\n          &lt;tr&gt;\n            &lt;td class="code"&gt;{{ n.name }}&lt;/td&gt;\n            &lt;td class="m"&gt;{{ n.deals }}&lt;/td&gt;\n            &lt;td class="text-truncate" style="max-width:320px"&gt;{{ n.example|default:"—" }}&lt;/td&gt;\n            &lt;td&gt;{% if n.used %}&lt;i class="fa-solid fa-check text-success me-1"&gt;&lt;/i&gt;{{ n.used }}{% else %}&lt;span class="text-muted"&gt;не используется&lt;/span&gt;{% endif %}&lt;/td&gt;\n          &lt;/tr&gt;\n        {% endfor %}\n        &lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n  {% endif %}\n\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-code"&gt;&lt;/i&gt;SQL приложения&lt;/span&gt;\n      &lt;span class="hint"&gt;замените :pdate на дату, например date \'2026-10-01\'&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="p-3"&gt;\n      {% for title, text in sql %}\n      &lt;details class="mb-2"{% if forloop.first %} open{% endif %}&gt;\n        &lt;summary&gt;{{ title }}&lt;/summary&gt;\n        &lt;pre class="sql mt-2"&gt;{{ text }}&lt;/pre&gt;\n      &lt;/details&gt;\n      {% endfor %}\n    &lt;/div&gt;\n  &lt;/div&gt;\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})
